{"content":"import type { BallId, Vec3Tuple } from '../types';
import { BALL_RADIUS, HALF_LENGTH, FOOT_SPOT } from './table';

// ─────────────────────────────────────────────────────────────────────────────
// 16 ball colors (standard 8-ball palette)
// ─────────────────────────────────────────────────────────────────────────────
export const BALL_COLORS: Record<BallId, string> = {
  0: '#FFFFFF',  // Cue ball
  1: '#FFD700',  // Yellow (solid)
  2: '#0000FF',  // Blue (solid)
  3: '#FF0000',  // Red (solid)
  4: '#800080',  // Purple (solid)
  5: '#FF8C00',  // Orange (solid)
  6: '#006400',  // Green (solid)
  7: '#8B0000',  // Maroon (solid)
  8: '#000000',  // Eight ball (black)
  9: '#FFD700',  // Yellow (stripe)
  10: '#0000FF', // Blue (stripe)
  11: '#FF0000', // Red (stripe)
  12: '#800080', // Purple (stripe)
  13: '#FF8C00', // Orange (stripe)
  14: '#006400', // Green (stripe)
  15: '#8B0000', // Maroon (stripe)
};

// ─────────────────────────────────────────────────────────────────────────────
// Helpers – ball classification
// ─────────────────────────────────────────────────────────────────────────────
/** Balls 1-7 are solids */
export function isSolid(id: BallId): boolean {
  return id >= 1 && id <= 7;
}

/** Balls 9-15 are stripes */
export function isStripe(id: BallId): boolean {
  return id >= 9 && id <= 15;
}

/** Ball 8 is the eight ball */
export function isEightBall(id: BallId): boolean {
  return id === 8;
}

/** Ball 0 is the cue ball */
export function isCueBall(id: BallId): boolean {
  return id === 0;
}

// ─────────────────────────────────────────────────────────────────────────────
// Standard 8-ball rack layout (triangle at foot spot)
//
// Row 0 (apex):  1 ball   →   solid
// Row 1:         2 balls  →   stripe, solid
// Row 2:         3 balls  →   solid, EIGHT, stripe
// Row 3:         4 balls  →   mixed
// Row 4 (base):  5 balls  →   corners: one solid + one stripe
// ─────────────────────────────────────────────────────────────────────────────
const RACK_ORDER: BallId[] = [
  // row 0
  1,
  // row 1
  9, 2,
  // row 2 (8-ball in centre)
  10, 8, 11,
  // row 3
  3, 14, 6, 15,
  // row 4 (corners: solid + stripe)
  4, 12, 7, 13, 5,
];

/**
 * Returns the 16 ball starting positions as `[x, y, z]` tuples.
 *
 * The apex ball sits on the foot spot; each subsequent row is offset along
 * the Z-axis by `BALL_RADIUS * 2 * cos(30°)`.  Columns within a row are
 * centred around X = 0 with `BALL_RADIUS * 2` spacing.
 */
export function getRackPositions(): Record<BallId, Vec3Tuple> {
  const positions: Record<number, Vec3Tuple> = {};
  const diameter = BALL_RADIUS * 2;
  const spacing = diameter * 1.02; // tiny gap to avoid initial overlap
  const rowDepth = spacing * Math.cos(Math.PI / 6); // cos(30°) ≈ 0.866

  let idx = 0;
  for (let row = 0; row < 5; row++) {
    const count = row + 1;
    const z = HALF_LENGTH / 2 + row * rowDepth;
    for (let col = 0; col < count; col++) {
      const x = (col - (count - 1) / 2) * spacing;
      positions[RACK_ORDER[idx]] = [x, BALL_RADIUS, z];
      idx++;
    }
  }

  // Cue ball behind the head string (~40 % from head rail)
  positions[0] = [0, BALL_RADIUS, -HALF_LENGTH * 0.4];

  return positions as Record<BallId, Vec3Tuple>;
}

/** Convenience: look up a ball's hex colour string */
export function getBallColor(id: BallId): string {
  return BALL_COLORS[id];
}","end_line":103,"start_line":0,"total_lines":104}

{"content":"import type { BallId } from '../types';
import { BALL_COLORS } from '../constants/balls';
import { isStripe } from '../types';

const TEXTURE_WIDTH = 512;
const TEXTURE_HEIGHT = 256;

/**
 * Generate a procedural canvas texture for a billiard ball (T09).
 *
 * - Cue ball (id 0): plain white
 * - Solid balls (1-7): solid color fill + white number circle
 * - Stripe balls (9-15): white background + colored band middle 50% + white number circle
 * - Eight ball (8): solid black + white number circle
 */
export function generateBallTexture(id: BallId): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = TEXTURE_WIDTH;
  canvas.height = TEXTURE_HEIGHT;
  const ctx = canvas.getContext('2d')!;

  if (id === 0) {
    // Cue ball: plain white
    ctx.fillStyle = '#F8F8FF';
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
    // Subtle gloss highlight baked into texture
    const gloss = ctx.createRadialGradient(
      TEXTURE_WIDTH * 0.35, TEXTURE_HEIGHT * 0.35, 0,
      TEXTURE_WIDTH * 0.35, TEXTURE_HEIGHT * 0.35, TEXTURE_WIDTH * 0.3,
    );
    gloss.addColorStop(0, 'rgba(255, 255, 255, 0.3)');
    gloss.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = gloss;
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
    return canvas;
  }

  const color = BALL_COLORS[id];
  const stripe = isStripe(id);

  if (stripe) {
    // Stripe ball: white background with colored band in middle 50%
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);

    // Color band covering middle 50% of UV height
    const bandTop = TEXTURE_HEIGHT * 0.25;
    const bandBottom = TEXTURE_HEIGHT * 0.75;
    ctx.fillStyle = color;
    ctx.fillRect(0, bandTop, TEXTURE_WIDTH, bandBottom - bandTop);
  } else {
    // Solid ball: entire surface is the ball color
    ctx.fillStyle = color;
    ctx.fillRect(0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);
  }

  // Number circle (white circle with black number)
  const cx = TEXTURE_WIDTH / 2;
  const cy = TEXTURE_HEIGHT / 2;
  const circleRadius = 30;

  ctx.beginPath();
  ctx.arc(cx, cy, circleRadius, 0, Math.PI * 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fill();
  ctx.strokeStyle = '#333333';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Number text
  ctx.fillStyle = '#000000';
  ctx.font = 'bold 28px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(id), cx, cy + 1);

  return canvas;
}

/**
 * Generate a felt texture for the table bed.
 * Dark green base with subtle noise grain.
 */
export function generateFeltTexture(): HTMLCanvasElement {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base green
  ctx.fillStyle = '#0d6b2e';
  ctx.fillRect(0, 0, size, size);

  // Add noise grain for felt-like appearance
  const imageData = ctx.getImageData(0, 0, size, size);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 15;
    data[i] = Math.max(0, Math.min(255, data[i] + noise));
    data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
    data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
  }
  ctx.putImageData(imageData, 0, 0);

  return canvas;
}

/**
 * Generate a wood grain texture for the rails.
 * Brown base with darker grain lines.
 */
export function generateWoodTexture(): HTMLCanvasElement {
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base brown
  ctx.fillStyle = '#5C3317';
  ctx.fillRect(0, 0, size, size);

  // Wood grain lines
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.15)';
  ctx.lineWidth = 1;
  for (let y = 0; y < size; y += 3 + Math.random() * 4) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    let x = 0;
    while (x < size) {
      x += 10 + Math.random() * 20;
      ctx.lineTo(x, y + (Math.random() - 0.5) * 2);
    }
    ctx.stroke();
  }

  return canvas;
}","end_line":138,"start_line":0,"total_lines":139}

{"content":"import { useMemo } from 'react';
import * as THREE from 'three';
import {
  TABLE_LENGTH,
  TABLE_WIDTH,
  RAIL_HEIGHT,
  RAIL_WIDTH,
  HALF_LENGTH,
  HALF_WIDTH,
  POCKET_POSITIONS,
  POCKET_RADIUS,
  CUSHION_THICKNESS,
  CUSHION_HEIGHT,
  BALL_RADIUS,
} from '../constants/table';
import { generateFeltTexture, generateWoodTexture } from '../utils/textures';

export default function Table() {
  const feltTexture = useMemo(() => {
    const canvas = generateFeltTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 8);
    return tex;
  }, []);

  const woodTexture = useMemo(() => {
    const canvas = generateWoodTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    return tex;
  }, []);

  // Long rail half-length (between side-pocket gap and corner-pocket gap)
  const longSegmentLength = HALF_LENGTH - RAIL_WIDTH * 1.2;
  // Short rail full length
  const shortRailLength = TABLE_WIDTH;

  return (
    <group>
      {/* ── Table Bed (green felt surface) ── */}
      <mesh position={[0, -0.005, 0]} receiveShadow>
        <boxGeometry args={[TABLE_WIDTH, 0.01, TABLE_LENGTH]} />
        <meshStandardMaterial color="#0d6b2e" map={feltTexture} roughness={0.9} />
      </mesh>

      {/* ── Wooden frame beneath bed ── */}
      <mesh position={[0, -0.025, 0]} receiveShadow>
        <boxGeometry
          args={[
            TABLE_WIDTH + RAIL_WIDTH * 2,
            0.03,
            TABLE_LENGTH + RAIL_WIDTH * 2,
          ]}
        />
        <meshStandardMaterial color="#3b1f0b" map={woodTexture} roughness={0.7} />
      </mesh>

      {/* ── Wooden Rails ── */}

      {/* Left rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Right rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Head rail (near end, Z negative) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, -HALF_LENGTH - RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* Foot rail (far end, Z positive) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, HALF_LENGTH + RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* ── Cushions (green rubber bumpers, slightly angled inward) ── */}

      {/* Head-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Head-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Left side cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH + CUSHION_THICKNESS / 2 + 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* Right side cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH - CUSHION_THICKNESS / 2 - 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* ── Pockets (6 dark circles) ── */}
      {POCKET_POSITIONS.map((pos, i) => (
        <group key={i} position={[pos[0], 0.001, pos[2]]}>
          {/* Pocket hole */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <circleGeometry args={[POCKET_RADIUS, 32]} />
            <meshStandardMaterial color="#050505" roughness={1} />
          </mesh>
          {/* Pocket rim */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[POCKET_RADIUS, POCKET_RADIUS + 0.006, 32]} />
            <meshStandardMaterial color="#2a1506" roughness={0.6} />
          </mesh>
        </group>
      ))}
    </group>
  );
}

/* ────────────────────────────────────────────────────────────────────────────
   Sub-components
   ──────────────────────────────────────────────────────────────────────────── */

function RailSegment({
  position,
  size,
  texture,
}: {
  position: [number, number, number];
  size: [number, number, number];
  texture: THREE.Texture;
}) {
  return (
    <mesh position={position} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial map={texture} color="#5C3317" roughness={0.65} />
    </mesh>
  );
}

function CushionSegment({
  position,
  size,
}: {
  position: [number, number, number];
  size: [number, number, number];
}) {
  return (
    <mesh position={position}>
      <boxGeometry args={size} />
      <meshStandardMaterial color="#0a8a3a" roughness={0.85} />
    </mesh>
  );
}","end_line":237,"start_line":0,"total_lines":238}

{"content":"import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import CueStick from './CueStick';
import AimLine from './AimLine';
import PhysicsWorld from '../physics/PhysicsWorld';
import useSettleDetector from '../hooks/useSettleDetector';
import useShotSequence from '../hooks/useShotSequence';
import {
  CAMERA_DEFAULT_POSITION,
  CAMERA_FOV,
  HALF_LENGTH,
  HALF_WIDTH,
} from '../constants/table';

/**
 * Wrapper for game hooks that must run inside the Canvas/Physics context.
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}

/**
 * R3F Canvas with shadow map, perspective camera (45 deg FOV) positioned above
 * the table at an angle, ambient + directional + point lights, and
 * OrbitControls constrained so the user cannot go below the table.
 */
export default function Scene() {
  const orbitTarget: [number, number, number] = [0, 0, 0];

  return (
    <Canvas
      shadows
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.01,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />

      {/* Lighting */}
      <ambientLight intensity={0.35} color="#ffffff" />
      <directionalLight
        position={[0, 3, 0.5]}
        intensity={1.2}
        color="#fffbe6"
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-far={10}
        shadow-camera-left={-HALF_WIDTH - 0.3}
        shadow-camera-right={HALF_WIDTH + 0.3}
        shadow-camera-top={HALF_LENGTH + 0.3}
        shadow-camera-bottom={-HALF_LENGTH - 0.3}
        shadow-bias={-0.0005}
      />
      <pointLight
        position={[-HALF_WIDTH * 0.4, 1.5, -HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />
      <pointLight
        position={[HALF_WIDTH * 0.4, 1.5, HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />

      {/* Physics world wrapping all game objects */}
      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      {/* Camera controls */}
      <OrbitControls
        target={orbitTarget}
        enablePan={false}
        enableDamping
        dampingFactor={0.08}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.15}
        minDistance={0.8}
        maxDistance={4.5}
      />

      {/* Floor plane */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -0.82, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#0e0806" />
      </mesh>

      <fog attach="fog" args={['#1a1a2e', 6, 14]} />
    </Canvas>
  );
}","end_line":111,"start_line":0,"total_lines":112}

