import type { BallId } from '../types';
import { BALL_COLORS } from '../constants/balls';
import { isStripe } from '../types';

// ─────────────────────────────────────────────────────────────────────────────
// T24: Enhanced texture resolution 1024×512 for sharper ball visuals
// ─────────────────────────────────────────────────────────────────────────────
const TEXTURE_WIDTH = 1024;
const TEXTURE_HEIGHT = 512;

/**
 * Generate a procedural canvas texture for a billiard ball (T24 enhanced).
 *
 * - Cue ball (id 0): plain white with subtle specular highlight
 * - Solid balls (1-7): solid color fill + white number circle
 * - Stripe balls (9-15): white background + colored band middle 50% + white number circle
 * - Eight ball (8): solid black + white number circle
 *
 * All balls get a baked-in subtle specular highlight for visual polish.
 * Numbers are anti-aliased via 2× downscale rendering for crisp edges.
 */
export function generateBallTexture(id: BallId): HTMLCanvasElement {
  // Render at 2× resolution then downscale for anti-aliased number text
  const scale = 2;
  const rw = TEXTURE_WIDTH * scale;
  const rh = TEXTURE_HEIGHT * scale;

  const renderCanvas = document.createElement('canvas');
  renderCanvas.width = rw;
  renderCanvas.height = rh;
  const ctx = renderCanvas.getContext('2d')!;

  // ── Base fill ──────────────────────────────────────────────────────────
  if (id === 0) {
    // Cue ball: plain white
    ctx.fillStyle = '#F8F8FF';
    ctx.fillRect(0, 0, rw, rh);
  } else {
    const color = BALL_COLORS[id];
    const stripe = isStripe(id);

    if (stripe) {
      // Stripe ball: white background with colored band in middle 50%
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, rw, rh);

      const bandTop = rh * 0.25;
      const bandBottom = rh * 0.75;
      ctx.fillStyle = color;
      ctx.fillRect(0, bandTop, rw, bandBottom - bandTop);

      // Soft feathered edges on stripe band for anti-aliased look
      const feather = rh * 0.02;
      const gradTop = ctx.createLinearGradient(0, bandTop - feather, 0, bandTop + feather);
      gradTop.addColorStop(0, 'rgba(255,255,255,1)');
      gradTop.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = gradTop;
      ctx.fillRect(0, bandTop - feather, rw, feather * 2);

      const gradBot = ctx.createLinearGradient(0, bandBottom - feather, 0, bandBottom + feather);
      gradBot.addColorStop(0, 'rgba(255,255,255,0)');
      gradBot.addColorStop(1, 'rgba(255,255,255,1)');
      ctx.fillStyle = gradBot;
      ctx.fillRect(0, bandBottom - feather, rw, feather * 2);
    } else {
      // Solid ball: entire surface is the ball color
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, rw, rh);
    }
  }

  // ── Number circle & text ───────────────────────────────────────────────
  if (id !== 0) {
    const cx = rw / 2;
    const cy = rh / 2;
    const circleRadius = 56 * scale; // proportional to larger canvas

    // White circle background
    ctx.beginPath();
    ctx.arc(cx, cy, circleRadius, 0, Math.PI * 2);
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();
    ctx.strokeStyle = '#444444';
    ctx.lineWidth = 1.5 * scale;
    ctx.stroke();

    // Anti-aliased number text (rendered large, will be downscaled)
    ctx.fillStyle = '#000000';
    ctx.font = `bold ${54 * scale}px Arial, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(id), cx, cy + 2 * scale);
  }

  // ── Baked specular highlight ───────────────────────────────────────────
  // Subtle specular highlight in the upper-left region of the texture,
  // simulating a light reflection baked into the surface.
  const specX = rw * 0.33;
  const specY = rh * 0.33;
  const specRadius = rw * 0.28;
  const specular = ctx.createRadialGradient(specX, specY, 0, specX, specY, specRadius);
  specular.addColorStop(0, 'rgba(255, 255, 255, 0.18)');
  specular.addColorStop(0.4, 'rgba(255, 255, 255, 0.06)');
  specular.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = specular;
  ctx.fillRect(0, 0, rw, rh);

  // ── Downscale to final resolution for anti-aliased result ──────────────
  const finalCanvas = document.createElement('canvas');
  finalCanvas.width = TEXTURE_WIDTH;
  finalCanvas.height = TEXTURE_HEIGHT;
  const fctx = finalCanvas.getContext('2d')!;
  fctx.imageSmoothingEnabled = true;
  fctx.imageSmoothingQuality = 'high';
  fctx.drawImage(renderCanvas, 0, 0, TEXTURE_WIDTH, TEXTURE_HEIGHT);

  return finalCanvas;
}

// ─────────────────────────────────────────────────────────────────────────────
// T25: Felt noise texture – canvas-generated subtle grain pattern
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Generate a felt texture for the table bed.
 * Dark green base with layered subtle noise grain for a realistic cloth look.
 * Uses a larger canvas (1024×1024) for finer grain detail.
 */
export function generateFeltTexture(): HTMLCanvasElement {
  const size = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base green
  ctx.fillStyle = '#0d6b2e';
  ctx.fillRect(0, 0, size, size);

  // Layer 1: coarse noise for fabric weave impression
  const imageData = ctx.getImageData(0, 0, size, size);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 12;
    data[i] = Math.max(0, Math.min(255, data[i] + noise));
    data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
    data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
  }
  ctx.putImageData(imageData, 0, 0);

  // Layer 2: subtle horizontal fibre lines (felt cloth direction)
  ctx.globalAlpha = 0.04;
  ctx.strokeStyle = '#000000';
  for (let y = 0; y < size; y += 2 + Math.random() * 3) {
    ctx.lineWidth = 0.5 + Math.random() * 0.5;
    ctx.beginPath();
    ctx.moveTo(0, y);
    let x = 0;
    while (x < size) {
      x += 8 + Math.random() * 16;
      ctx.lineTo(x, y + (Math.random() - 0.5) * 1.5);
    }
    ctx.stroke();
  }
  ctx.globalAlpha = 1.0;

  // Layer 3: very subtle vertical cross-fibres
  ctx.globalAlpha = 0.02;
  for (let x = 0; x < size; x += 3 + Math.random() * 4) {
    ctx.lineWidth = 0.3 + Math.random() * 0.4;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    let y = 0;
    while (y < size) {
      y += 8 + Math.random() * 16;
      ctx.lineTo(x + (Math.random() - 0.5) * 1.0, y);
    }
    ctx.stroke();
  }
  ctx.globalAlpha = 1.0;

  return canvas;
}

// ─────────────────────────────────────────────────────────────────────────────
// T25: Wood grain texture – brown gradient with dark grain lines
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Generate a wood grain texture for the rails.
 * Rich brown gradient base with darker grain lines and subtle variation
 * for a realistic polished wood appearance.
 */
export function generateWoodTexture(): HTMLCanvasElement {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Base brown gradient (slight vertical variation for depth)
  const baseGrad = ctx.createLinearGradient(0, 0, 0, size);
  baseGrad.addColorStop(0, '#6B3A20');
  baseGrad.addColorStop(0.3, '#5C3317');
  baseGrad.addColorStop(0.7, '#4E2B14');
  baseGrad.addColorStop(1, '#5A3018');
  ctx.fillStyle = baseGrad;
  ctx.fillRect(0, 0, size, size);

  // Subtle horizontal colour variation
  ctx.globalAlpha = 0.06;
  for (let x = 0; x < size; x += 20 + Math.random() * 40) {
    const w = 10 + Math.random() * 30;
    const lightness = Math.random() > 0.5 ? '#8B5E3C' : '#3A1F0D';
    ctx.fillStyle = lightness;
    ctx.fillRect(x, 0, w, size);
  }
  ctx.globalAlpha = 1.0;

  // Primary dark grain lines (the main visible grain)
  ctx.globalAlpha = 0.18;
  for (let y = 0; y < size; y += 3 + Math.random() * 5) {
    ctx.strokeStyle = `rgba(0, 0, 0, ${0.1 + Math.random() * 0.15})`;
    ctx.lineWidth = 0.5 + Math.random() * 1.2;
    ctx.beginPath();
    ctx.moveTo(0, y);
    let x = 0;
    while (x < size) {
      x += 8 + Math.random() * 20;
      ctx.lineTo(x, y + (Math.random() - 0.5) * 2.5);
    }
    ctx.stroke();
  }
  ctx.globalAlpha = 1.0;

  // Occasional knot / wider grain feature
  ctx.globalAlpha = 0.08;
  for (let k = 0; k < 3; k++) {
    const kx = Math.random() * size;
    const ky = Math.random() * size;
    const kr = 5 + Math.random() * 10;
    const knotGrad = ctx.createRadialGradient(kx, ky, 0, kx, ky, kr);
    knotGrad.addColorStop(0, '#2A1508');
    knotGrad.addColorStop(1, 'rgba(42, 21, 8, 0)');
    ctx.fillStyle = knotGrad;
    ctx.fillRect(kx - kr, ky - kr, kr * 2, kr * 2);
  }
  ctx.globalAlpha = 1.0;

  // Fine noise over the top for micro-texture
  const imgData = ctx.getImageData(0, 0, size, size);
  const px = imgData.data;
  for (let i = 0; i < px.length; i += 4) {
    const n = (Math.random() - 0.5) * 8;
    px[i] = Math.max(0, Math.min(255, px[i] + n));
    px[i + 1] = Math.max(0, Math.min(255, px[i + 1] + n));
    px[i + 2] = Math.max(0, Math.min(255, px[i + 2] + n));
  }
  ctx.putImageData(imgData, 0, 0);

  return canvas;
}

import { useMemo } from 'react';
import * as THREE from 'three';
import {
  TABLE_LENGTH,
  TABLE_WIDTH,
  RAIL_HEIGHT,
  RAIL_WIDTH,
  HALF_LENGTH,
  HALF_WIDTH,
  POCKET_POSITIONS,
  POCKET_RADIUS,
  CUSHION_THICKNESS,
  CUSHION_HEIGHT,
  BALL_RADIUS,
  FLOOR_Y,
} from '../constants/table';
import { generateFeltTexture, generateWoodTexture } from '../utils/textures';

/**
 * Standard diamond sight positions on a pool table:
 * - Each long rail has 7 diamonds (3 per half + center)
 * - Each short rail has 3 diamonds
 * - Evenly spaced along the playing surface edge
 */

/** Diamond sight marker component */
function DiamondSight({
  position,
  rotation,
}: {
  position: [number, number, number];
  rotation?: [number, number, number];
}) {
  // Small diamond shape (~8mm tall) on the rail top surface
  const d = 0.008; // diamond half-size
  return (
    <mesh position={position} rotation={rotation} renderOrder={1}>
      {/* Use a small rotated plane with diamond-shaped geometry approximated by a box */}
      <boxGeometry args={[d * 2, 0.002, d * 2]} />
      <meshStandardMaterial
        color="#c4a265"
        roughness={0.4}
        metalness={0.2}
      />
    </mesh>
  );
}

export default function Table() {
  const feltTexture = useMemo(() => {
    const canvas = generateFeltTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 8);
    return tex;
  }, []);

  const woodTexture = useMemo(() => {
    const canvas = generateWoodTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    return tex;
  }, []);

  // Long rail half-length (between side-pocket gap and corner-pocket gap)
  const longSegmentLength = HALF_LENGTH - RAIL_WIDTH * 1.2;
  // Short rail full length
  const shortRailLength = TABLE_WIDTH;

  // ── Diamond sight positions ──
  // Long rails: 7 diamonds evenly spaced along the Z-axis playing surface
  // Short rails: 3 diamonds evenly spaced along the X-axis playing surface
  const diamondY = RAIL_HEIGHT + 0.001; // sit on top of rail
  const longRailInset = RAIL_WIDTH * 0.35; // how far into the rail from edge

  // Long rail diamond Z positions (7 marks: divide playing length into 8 segments)
  const longDiamondZs = useMemo(() => {
    const positions: number[] = [];
    const segCount = 8;
    for (let i = 1; i < segCount; i++) {
      positions.push(-HALF_LENGTH + (TABLE_LENGTH / segCount) * i);
    }
    return positions;
  }, []);

  // Short rail diamond X positions (3 marks: divide playing width into 4 segments)
  const shortDiamondXs = useMemo(() => {
    const positions: number[] = [];
    const segCount = 4;
    for (let i = 1; i < segCount; i++) {
      positions.push(-HALF_WIDTH + (TABLE_WIDTH / segCount) * i);
    }
    return positions;
  }, []);

  return (
    <group>
      {/* ── Table Bed (green felt surface) ── */}
      <mesh position={[0, -0.005, 0]} receiveShadow>
        <boxGeometry args={[TABLE_WIDTH, 0.01, TABLE_LENGTH]} />
        <meshStandardMaterial color="#0d6b2e" map={feltTexture} roughness={0.9} />
      </mesh>

      {/* ── Wooden frame beneath bed ── */}
      <mesh position={[0, -0.025, 0]} receiveShadow>
        <boxGeometry
          args={[
            TABLE_WIDTH + RAIL_WIDTH * 2,
            0.03,
            TABLE_LENGTH + RAIL_WIDTH * 2,
          ]}
        />
        <meshStandardMaterial color="#3b1f0b" map={woodTexture} roughness={0.7} />
      </mesh>

      {/* ── Wooden Rails ── */}

      {/* Left rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          -HALF_WIDTH - RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Right rail – two segments (gap at middle for side pocket) */}
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          -HALF_LENGTH / 2 - RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />
      <RailSegment
        position={[
          HALF_WIDTH + RAIL_WIDTH / 2,
          RAIL_HEIGHT / 2,
          HALF_LENGTH / 2 + RAIL_WIDTH / 4,
        ]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, longSegmentLength]}
        texture={woodTexture}
      />

      {/* Head rail (near end, Z negative) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, -HALF_LENGTH - RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* Foot rail (far end, Z positive) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, HALF_LENGTH + RAIL_WIDTH / 2]}
        size={[shortRailLength, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* ── Diamond Sight Markers ── */}

      {/* Left rail diamonds */}
      {longDiamondZs.map((z, i) => (
        <DiamondSight
          key={`left-diamond-${i}`}
          position={[-HALF_WIDTH - longRailInset, diamondY, z]}
          rotation={[0, Math.PI / 4, 0]}
        />
      ))}

      {/* Right rail diamonds */}
      {longDiamondZs.map((z, i) => (
        <DiamondSight
          key={`right-diamond-${i}`}
          position={[HALF_WIDTH + longRailInset, diamondY, z]}
          rotation={[0, Math.PI / 4, 0]}
        />
      ))}

      {/* Head rail diamonds */}
      {shortDiamondXs.map((x, i) => (
        <DiamondSight
          key={`head-diamond-${i}`}
          position={[x, diamondY, -HALF_LENGTH - RAIL_WIDTH * 0.35]}
          rotation={[0, Math.PI / 4, 0]}
        />
      ))}

      {/* Foot rail diamonds */}
      {shortDiamondXs.map((x, i) => (
        <DiamondSight
          key={`foot-diamond-${i}`}
          position={[x, diamondY, HALF_LENGTH + RAIL_WIDTH * 0.35]}
          rotation={[0, Math.PI / 4, 0]}
        />
      ))}

      {/* ── Cushions (green rubber bumpers, slightly angled inward) ── */}

      {/* Head-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Head-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          -HALF_LENGTH + CUSHION_THICKNESS / 2 + 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end left cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH / 2 - RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Foot-end right cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH / 2 + RAIL_WIDTH * 0.3,
          CUSHION_HEIGHT / 2,
          HALF_LENGTH - CUSHION_THICKNESS / 2 - 0.005,
        ]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.4, CUSHION_HEIGHT, CUSHION_THICKNESS]}
      />

      {/* Left side cushion */}
      <CushionSegment
        position={[
          -HALF_WIDTH + CUSHION_THICKNESS / 2 + 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* Right side cushion */}
      <CushionSegment
        position={[
          HALF_WIDTH - CUSHION_THICKNESS / 2 - 0.005,
          CUSHION_HEIGHT / 2,
          0,
        ]}
        size={[
          CUSHION_THICKNESS,
          CUSHION_HEIGHT,
          TABLE_LENGTH - RAIL_WIDTH * 3,
        ]}
      />

      {/* ── Pockets (6 dark circles) ── */}
      {POCKET_POSITIONS.map((pos, i) => (
        <group key={i} position={[pos[0], 0.001, pos[2]]}>
          {/* Pocket hole */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <circleGeometry args={[POCKET_RADIUS, 32]} />
            <meshStandardMaterial color="#050505" roughness={1} />
          </mesh>
          {/* Pocket rim */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[POCKET_RADIUS, POCKET_RADIUS + 0.006, 32]} />
            <meshStandardMaterial color="#2a1506" roughness={0.6} />
          </mesh>
        </group>
      ))}

      {/* ── Dark floor plane beneath table ── */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, FLOOR_Y, 0]}
        receiveShadow
      >
        <planeGeometry args={[12, 14]} />
        <meshStandardMaterial color="#0a0604" roughness={0.95} />
      </mesh>

      {/* ── Table legs (4 cylindrical legs) ── */}
      <TableLeg position={[-HALF_WIDTH - 0.01, FLOOR_Y / 2, -HALF_LENGTH - 0.01]} />
      <TableLeg position={[HALF_WIDTH + 0.01, FLOOR_Y / 2, -HALF_LENGTH - 0.01]} />
      <TableLeg position={[-HALF_WIDTH - 0.01, FLOOR_Y / 2, HALF_LENGTH + 0.01]} />
      <TableLeg position={[HALF_WIDTH + 0.01, FLOOR_Y / 2, HALF_LENGTH + 0.01]} />
    </group>
  );
}

/* ────────────────────────────────────────────────────────────────────────────
   Sub-components
   ──────────────────────────────────────────────────────────────────────────── */

function RailSegment({
  position,
  size,
  texture,
}: {
  position: [number, number, number];
  size: [number, number, number];
  texture: THREE.Texture;
}) {
  return (
    <mesh position={position} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial map={texture} color="#5C3317" roughness={0.65} />
    </mesh>
  );
}

function CushionSegment({
  position,
  size,
}: {
  position: [number, number, number];
  size: [number, number, number];
}) {
  return (
    <mesh position={position}>
      <boxGeometry args={size} />
      <meshStandardMaterial color="#0a8a3a" roughness={0.85} />
    </mesh>
  );
}

function TableLeg({
  position,
}: {
  position: [number, number, number];
}) {
  const legHeight = Math.abs(position[1]) * 2;
  return (
    <mesh position={position} castShadow receiveShadow>
      <cylinderGeometry args={[0.03, 0.035, legHeight, 12]} />
      <meshStandardMaterial color="#3b1f0b" roughness={0.7} />
    </mesh>
  );
}

import { Canvas } from '@react-three/fiber';
import * as THREE from 'three';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import CueStick from './CueStick';
import AimLine from './AimLine';
import PhysicsWorld from '../physics/PhysicsWorld';
import useSettleDetector from '../hooks/useSettleDetector';
import useShotSequence from '../hooks/useShotSequence';
import {
  CAMERA_DEFAULT_POSITION,
  CAMERA_FOV,
  HALF_LENGTH,
  HALF_WIDTH,
  FLOOR_Y,
} from '../constants/table';

/**
 * Wrapper for game hooks that must run inside the Canvas/Physics context.
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}

/**
 * R3F Canvas with PCFSoftShadowMap (2048×2048), perspective camera (45 deg FOV)
 * positioned above the table at an angle, ambient + directional + point lights,
 * and OrbitControls constrained so the user cannot go below the table.
 *
 * Phase 8 (T25): shadow map upgraded to PCFSoftShadowMap for soft shadow edges,
 * directional light shadow camera covers the full table area, balls cast shadows
 * onto the felt surface.
 */
export default function Scene() {
  const orbitTarget: [number, number, number] = [0, 0, 0];

  return (
    <Canvas
      shadows
      gl={{
        shadowMap: {
          enabled: true,
          type: THREE.PCFSoftShadowMap,
        },
      }}
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.01,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />

      {/* Lighting */}
      <ambientLight intensity={0.35} color="#ffffff" />
      <directionalLight
        position={[0, 3, 0.5]}
        intensity={1.2}
        color="#fffbe6"
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-near={0.5}
        shadow-camera-far={8}
        shadow-camera-left={-HALF_WIDTH - 0.3}
        shadow-camera-right={HALF_WIDTH + 0.3}
        shadow-camera-top={HALF_LENGTH + 0.3}
        shadow-camera-bottom={-HALF_LENGTH - 0.3}
        shadow-bias={-0.0005}
        shadow-normalBias={0.02}
      />
      <pointLight
        position={[-HALF_WIDTH * 0.4, 1.5, -HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />
      <pointLight
        position={[HALF_WIDTH * 0.4, 1.5, HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />

      {/* Physics world wrapping all game objects */}
      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      {/* Camera controls */}
      <OrbitControls
        target={orbitTarget}
        enablePan={false}
        enableDamping
        dampingFactor={0.08}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.15}
        minDistance={0.8}
        maxDistance={4.5}
      />

      {/* ── Dark floor plane beneath table (Phase 8, T25) ── */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, FLOOR_Y, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#0e0806" roughness={0.95} metalness={0} />
      </mesh>

      <fog attach="fog" args={['#1a1a2e', 6, 14]} />
    </Canvas>
  );
}

